bool PathEquals(const std::wstring& first, const std::wstring& second) {
    return CompareStringOrdinal(first.c_str(), -1, second.c_str(), -1, TRUE) == CSTR_EQUAL;
}

std::wstring NormalizePath(const std::wstring& path) {
    const DWORD required = GetFullPathNameW(path.c_str(), 0, nullptr, nullptr);
    if (required == 0) {
        return path;
    }
    std::wstring normalized(static_cast<std::size_t>(required), L'\0');
    const DWORD written = GetFullPathNameW(path.c_str(), required, normalized.data(), nullptr);
    if (written == 0 || written >= required) {
        return path;
    }
    normalized.resize(written);
    return normalized;
}

std::wstring CurrentExecutablePath() {
    // Windows executable paths may exceed MAX_PATH when long-path support is
    // enabled. Keep the registry command exact rather than silently truncating
    // it to an old fixed buffer.
    std::wstring buffer(32768, L'\0');
    const DWORD written = GetModuleFileNameW(
        nullptr, buffer.data(), static_cast<DWORD>(buffer.size()));
    if (written == 0 || written >= buffer.size()) {
        return {};
    }
    buffer.resize(written);
    return NormalizePath(buffer);
}

bool IsDevelopmentBuildExecutable(const std::wstring& executablePath) {
    if (executablePath.empty()) {
        return false;
    }
    // The checked-in project builds to <project>\\out\\<configuration>.
    // Treat only that layout as development so a formal installed release
    // never overwrites the user's official GravityDesktop Run value.
    const std::filesystem::path executable(executablePath);
    const std::filesystem::path projectRoot =
        executable.parent_path().parent_path().parent_path();
    std::error_code error;
    return std::filesystem::exists(
        projectRoot / L"GravityDesktop.sln", error) && !error;
}

const wchar_t* AutoStartRegistryValueName(
    const std::wstring& executablePath) {
    return IsDevelopmentBuildExecutable(executablePath)
        ? kDevelopmentAutoStartRegistryValueName
        : kAutoStartRegistryValueName;
}

std::wstring BuildAutoStartCommand(
    const std::wstring& executablePath) {
    if (executablePath.empty()) {
        return {};
    }
    return L"\"" + executablePath + L"\" --autostart";
}

bool AutoStartCommandMatches(
    const std::wstring& command,
    const std::wstring& expectedExecutablePath) {
    if (command.empty() || expectedExecutablePath.empty()) {
        return false;
    }
    int argumentCount = 0;
    LPWSTR* arguments = CommandLineToArgvW(
        command.c_str(), &argumentCount);
    if (arguments == nullptr) {
        return false;
    }
    const bool matches =
        argumentCount == 2 &&
        PathEquals(NormalizePath(arguments[0]), expectedExecutablePath) &&
        CompareStringOrdinal(
            arguments[1], -1, L"--autostart", -1, TRUE) == CSTR_EQUAL;
    LocalFree(arguments);
    return matches;
}

enum class AutoStartRegistrationState : int {
    Disabled = 0,
    Enabled = 1,
    NeedsRepair = 2,
    Unavailable = 3,
};

struct AutoStartRegistrationStatus {
    AutoStartRegistrationState state =
        AutoStartRegistrationState::Unavailable;
    LONG error = ERROR_SUCCESS;
    std::wstring valueName;
};

AutoStartRegistrationStatus ReadAutoStartRegistration() {
    AutoStartRegistrationStatus status;
    const std::wstring executablePath = CurrentExecutablePath();
    if (executablePath.empty()) {
        status.error = GetLastError();
        return status;
    }
    status.valueName = AutoStartRegistryValueName(executablePath);

    HKEY key = nullptr;
    LONG result = RegOpenKeyExW(
        HKEY_CURRENT_USER, kAutoStartRegistrySubkey, 0,
        KEY_QUERY_VALUE, &key);
    if (result == ERROR_FILE_NOT_FOUND) {
        status.state = AutoStartRegistrationState::Disabled;
        return status;
    }
    if (result != ERROR_SUCCESS) {
        status.error = result;
        return status;
    }

    DWORD type = 0;
    DWORD byteCount = 0;
    result = RegQueryValueExW(
        key, status.valueName.c_str(), nullptr,
        &type, nullptr, &byteCount);
    if (result == ERROR_FILE_NOT_FOUND) {
        RegCloseKey(key);
        status.state = AutoStartRegistrationState::Disabled;
        return status;
    }
    if (result != ERROR_SUCCESS ||
        (type != REG_SZ && type != REG_EXPAND_SZ) ||
        byteCount < sizeof(wchar_t)) {
        RegCloseKey(key);
        status.state = result == ERROR_SUCCESS
            ? AutoStartRegistrationState::NeedsRepair
            : AutoStartRegistrationState::Unavailable;
        status.error = result;
        return status;
    }

    std::wstring value(
        static_cast<std::size_t>(byteCount / sizeof(wchar_t)), L'\0');
    result = RegQueryValueExW(
        key, status.valueName.c_str(), nullptr,
        &type, reinterpret_cast<BYTE*>(value.data()), &byteCount);
    RegCloseKey(key);
    if (result != ERROR_SUCCESS) {
        status.error = result;
        return status;
    }
    while (!value.empty() && value.back() == L'\0') {
        value.pop_back();
    }
    if (type == REG_EXPAND_SZ) {
        const DWORD expandedLength = ExpandEnvironmentStringsW(
            value.c_str(), nullptr, 0);
        if (expandedLength == 0) {
            status.state = AutoStartRegistrationState::NeedsRepair;
            status.error = GetLastError();
            return status;
        }
        std::wstring expanded(
            static_cast<std::size_t>(expandedLength), L'\0');
        if (ExpandEnvironmentStringsW(
                value.c_str(), expanded.data(), expandedLength) == 0) {
            status.state = AutoStartRegistrationState::NeedsRepair;
            status.error = GetLastError();
            return status;
        }
        expanded.resize(expandedLength - 1);
        value = std::move(expanded);
    }
    status.state = AutoStartCommandMatches(value, executablePath)
        ? AutoStartRegistrationState::Enabled
        : AutoStartRegistrationState::NeedsRepair;
    return status;
}

bool WriteAutoStartRegistration(bool enabled) {
    const std::wstring executablePath = CurrentExecutablePath();
    if (executablePath.empty()) {
        return false;
    }
    const wchar_t* valueName =
        AutoStartRegistryValueName(executablePath);
    HKEY key = nullptr;
    const LONG openResult = enabled
        ? RegCreateKeyExW(
              HKEY_CURRENT_USER, kAutoStartRegistrySubkey, 0,
              nullptr, REG_OPTION_NON_VOLATILE,
              KEY_QUERY_VALUE | KEY_SET_VALUE, nullptr, &key, nullptr)
        : RegOpenKeyExW(
              HKEY_CURRENT_USER, kAutoStartRegistrySubkey, 0,
              KEY_QUERY_VALUE | KEY_SET_VALUE, &key);
    if (!enabled && openResult == ERROR_FILE_NOT_FOUND) {
        return true;
    }
    if (openResult != ERROR_SUCCESS) {
        return false;
    }
    LONG result = ERROR_SUCCESS;
    if (enabled) {
        const std::wstring command = BuildAutoStartCommand(executablePath);
        const DWORD bytes = static_cast<DWORD>(
            (command.size() + 1) * sizeof(wchar_t));
        result = RegSetValueExW(
            key, valueName, 0, REG_SZ,
            reinterpret_cast<const BYTE*>(command.c_str()), bytes);
    } else {
        result = RegDeleteValueW(key, valueName);
        if (result == ERROR_FILE_NOT_FOUND) {
            result = ERROR_SUCCESS;
        }
    }
    RegCloseKey(key);
    if (result != ERROR_SUCCESS) {
        return false;
    }
    const AutoStartRegistrationStatus actual =
        ReadAutoStartRegistration();
    return actual.state ==
        (enabled ? AutoStartRegistrationState::Enabled
                 : AutoStartRegistrationState::Disabled);
}

bool RemoveAutoStartRegistrationForUninstall() {
    return WriteAutoStartRegistration(false);
}

std::int64_t UnixTimeNow() {
    return std::chrono::duration_cast<std::chrono::seconds>(
               std::chrono::system_clock::now().time_since_epoch())
        .count();
}

std::wstring FormatTimestamp(std::int64_t timestamp) {
    if (timestamp <= 0) {
        return L"从未使用";
    }
    const std::time_t value = static_cast<std::time_t>(timestamp);
    std::tm local{};
    if (localtime_s(&local, &value) != 0) {
        return L"时间未知";
    }
    wchar_t buffer[64]{};
    if (wcsftime(buffer, std::size(buffer), L"%Y-%m-%d %H:%M", &local) == 0) {
        return L"时间未知";
    }
    return buffer;
}

std::optional<std::string> ReadUtf8File(const std::filesystem::path& path) {
    std::ifstream stream(path, std::ios::binary);
    if (!stream) {
        return std::nullopt;
    }
    return std::string(std::istreambuf_iterator<char>(stream), std::istreambuf_iterator<char>());
}

bool WriteUtf8Atomic(const std::filesystem::path& target, const std::string& data) {
    std::error_code error;
    std::filesystem::create_directories(target.parent_path(), error);
    if (error) {
        return false;
    }

    const std::filesystem::path temporary = target.wstring() + L".tmp";
    const std::filesystem::path backup = target.wstring() + L".bak";
    HANDLE file = CreateFileW(temporary.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS,
                              FILE_ATTRIBUTE_NORMAL | FILE_FLAG_WRITE_THROUGH, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        return false;
    }

    DWORD written = 0;
    const bool writeSucceeded =
        data.size() <= MAXDWORD &&
        WriteFile(file, data.data(), static_cast<DWORD>(data.size()), &written, nullptr) != FALSE &&
        written == data.size() && FlushFileBuffers(file) != FALSE;
    CloseHandle(file);
    if (!writeSucceeded) {
        DeleteFileW(temporary.c_str());
        return false;
    }

    if (GetFileAttributesW(target.c_str()) != INVALID_FILE_ATTRIBUTES) {
        if (ReplaceFileW(target.c_str(), temporary.c_str(), backup.c_str(),
                         REPLACEFILE_WRITE_THROUGH, nullptr, nullptr) != FALSE) {
            return true;
        }
    }

    if (MoveFileExW(temporary.c_str(), target.c_str(),
                    MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH) != FALSE) {
        return true;
    }
    DeleteFileW(temporary.c_str());
    return false;
}

void AppendZipUInt16(std::vector<std::uint8_t>& bytes, std::uint16_t value) {
    bytes.push_back(static_cast<std::uint8_t>(value & 0xFF));
    bytes.push_back(static_cast<std::uint8_t>((value >> 8) & 0xFF));
}

void AppendZipUInt32(std::vector<std::uint8_t>& bytes, std::uint32_t value) {
    AppendZipUInt16(bytes, static_cast<std::uint16_t>(value & 0xFFFF));
    AppendZipUInt16(bytes, static_cast<std::uint16_t>((value >> 16) & 0xFFFF));
}

std::uint32_t Crc32ForZip(std::string_view data) {
    std::uint32_t value = 0xFFFFFFFFU;
    for (const unsigned char byte : data) {
        value ^= byte;
        for (int bit = 0; bit < 8; ++bit) {
            value = (value >> 1) ^
                ((value & 1U) != 0 ? 0xEDB88320U : 0U);
        }
    }
    return value ^ 0xFFFFFFFFU;
}

struct ZipStoredEntry {
    std::string name;
    std::string data;
};

// Diagnostic reports use the ZIP "store" method only.  It avoids a runtime
// compression dependency and is sufficient for the bounded log payload.
bool WriteStoredZip(const std::filesystem::path& target,
                    const std::vector<ZipStoredEntry>& entries) {
    struct CentralRecord {
        const ZipStoredEntry* entry = nullptr;
        std::uint32_t offset = 0;
        std::uint32_t crc = 0;
    };
    std::vector<std::uint8_t> bytes;
    std::vector<CentralRecord> records;
    records.reserve(entries.size());
    for (const ZipStoredEntry& entry : entries) {
        if (entry.name.empty() ||
            entry.name.size() > UINT16_MAX ||
            entry.data.size() > UINT32_MAX ||
            bytes.size() > UINT32_MAX) {
            return false;
        }
        const std::uint32_t offset = static_cast<std::uint32_t>(bytes.size());
        const std::uint32_t crc = Crc32ForZip(entry.data);
        AppendZipUInt32(bytes, 0x04034B50U);
        AppendZipUInt16(bytes, 20);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt32(bytes, crc);
        AppendZipUInt32(bytes, static_cast<std::uint32_t>(entry.data.size()));
        AppendZipUInt32(bytes, static_cast<std::uint32_t>(entry.data.size()));
        AppendZipUInt16(bytes, static_cast<std::uint16_t>(entry.name.size()));
        AppendZipUInt16(bytes, 0);
        bytes.insert(bytes.end(), entry.name.begin(), entry.name.end());
        bytes.insert(bytes.end(), entry.data.begin(), entry.data.end());
        records.push_back({&entry, offset, crc});
    }
    if (bytes.size() > UINT32_MAX) return false;
    const std::uint32_t centralOffset = static_cast<std::uint32_t>(bytes.size());
    for (const CentralRecord& record : records) {
        const ZipStoredEntry& entry = *record.entry;
        AppendZipUInt32(bytes, 0x02014B50U);
        AppendZipUInt16(bytes, 20);
        AppendZipUInt16(bytes, 20);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt32(bytes, record.crc);
        AppendZipUInt32(bytes, static_cast<std::uint32_t>(entry.data.size()));
        AppendZipUInt32(bytes, static_cast<std::uint32_t>(entry.data.size()));
        AppendZipUInt16(bytes, static_cast<std::uint16_t>(entry.name.size()));
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt16(bytes, 0);
        AppendZipUInt32(bytes, 0);
        AppendZipUInt32(bytes, record.offset);
        bytes.insert(bytes.end(), entry.name.begin(), entry.name.end());
    }
    if (bytes.size() > UINT32_MAX) return false;
    const std::uint32_t centralSize =
        static_cast<std::uint32_t>(bytes.size()) - centralOffset;
    if (records.size() > UINT16_MAX) return false;
    AppendZipUInt32(bytes, 0x06054B50U);
    AppendZipUInt16(bytes, 0);
    AppendZipUInt16(bytes, 0);
    AppendZipUInt16(bytes, static_cast<std::uint16_t>(records.size()));
    AppendZipUInt16(bytes, static_cast<std::uint16_t>(records.size()));
    AppendZipUInt32(bytes, centralSize);
    AppendZipUInt32(bytes, centralOffset);
    AppendZipUInt16(bytes, 0);
    return WriteUtf8Atomic(
        target,
        std::string(reinterpret_cast<const char*>(bytes.data()), bytes.size()));
}

template <typename WriteOperation>
bool CommitImportedStateWrite(bool& recoveryBlocked,
                              WriteOperation&& writeOperation) {
    const bool recoveryWasBlocked = recoveryBlocked;
    if (!std::forward<WriteOperation>(writeOperation)()) {
        recoveryBlocked = recoveryWasBlocked;
        return false;
    }
    recoveryBlocked = false;
    return true;
}

std::filesystem::path StateFilePath() {
    const DWORD overrideLength =
        GetEnvironmentVariableW(L"GRAVITY_DESKTOP_STATE_FILE", nullptr, 0);
    if (overrideLength > 1) {
        std::wstring overridePath(static_cast<std::size_t>(overrideLength),
                                  L'\0');
        const DWORD written = GetEnvironmentVariableW(
            L"GRAVITY_DESKTOP_STATE_FILE", overridePath.data(),
            overrideLength);
        if (written > 0 && written < overrideLength) {
            overridePath.resize(written);
            return std::filesystem::path(overridePath);
        }
    }
    PWSTR localAppData = nullptr;
    if (FAILED(SHGetKnownFolderPath(FOLDERID_LocalAppData, KF_FLAG_DEFAULT, nullptr,
                                    &localAppData))) {
        return std::filesystem::current_path() / L"state.json";
    }
    std::filesystem::path path(localAppData);
    CoTaskMemFree(localAppData);
    return path / L"GravityDesktop" / L"state.json";
}

std::wstring BackupTimestamp() {
    SYSTEMTIME time{};
    GetLocalTime(&time);
    wchar_t value[48]{};
    swprintf_s(value, L"%04u%02u%02u-%02u%02u%02u-%03u",
              time.wYear, time.wMonth, time.wDay, time.wHour, time.wMinute,
              time.wSecond, time.wMilliseconds);
    return value;
}

bool IsGeneratedHistorySnapshotName(
    const std::filesystem::path& path) {
    const std::wstring name = path.filename().wstring();
    if (name.size() != 30 ||
        name.compare(0, 6, L"state-") != 0 ||
        name.compare(25, 5, L".json") != 0 ||
        name[14] != L'-' || name[21] != L'-') {
        return false;
    }
    for (std::size_t index = 6; index < 25; ++index) {
        if (index == 14 || index == 21) {
            continue;
        }
        if (!iswdigit(name[index])) {
            return false;
        }
    }
    return true;
}

bool IsGeneratedRelationshipManifestSnapshotName(
    const std::filesystem::path& path) {
    const std::wstring name = path.filename().wstring();
    constexpr std::wstring_view kPrefix = L"relationships-";
    if (name.size() != kPrefix.size() + 19 + 5 ||
        name.compare(0, kPrefix.size(), kPrefix) != 0 ||
        name.compare(name.size() - 5, 5, L".json") != 0) {
        return false;
    }
    const std::wstring_view timestamp(
        name.data() + kPrefix.size(), 19);
    if (timestamp[8] != L'-' || timestamp[15] != L'-') {
        return false;
    }
    for (std::size_t index = 0; index < timestamp.size(); ++index) {
        if (index == 8 || index == 15) continue;
        if (!iswdigit(timestamp[index])) return false;
    }
    return true;
}

bool PruneGeneratedHistorySnapshots(
    const std::filesystem::path& folder) {
    std::error_code error;
    if (!std::filesystem::exists(folder, error)) {
        return !error;
    }
    std::vector<std::filesystem::path> snapshots;
    std::filesystem::directory_iterator iterator(folder, error);
    const std::filesystem::directory_iterator end;
    while (!error && iterator != end) {
        const std::filesystem::directory_entry& entry = *iterator;
        const std::filesystem::file_status status =
            entry.symlink_status(error);
        if (error) {
            break;
        }
        if (std::filesystem::is_regular_file(status) &&
            IsGeneratedHistorySnapshotName(entry.path())) {
            snapshots.push_back(entry.path());
        }
        iterator.increment(error);
    }
    if (error) {
        return false;
    }
    std::sort(
        snapshots.begin(), snapshots.end(),
        [](const std::filesystem::path& first,
           const std::filesystem::path& second) {
            return first.filename().wstring() >
                   second.filename().wstring();
        });

    std::set<std::wstring> retainedDailyDates;
    for (std::size_t index = kHistoryRecentSnapshotCount;
         index < snapshots.size(); ++index) {
        const std::wstring name =
            snapshots[index].filename().wstring();
        const std::wstring date = name.substr(6, 8);
        if (retainedDailyDates.size() <
                kHistoryDailySnapshotCount &&
            retainedDailyDates.insert(date).second) {
            continue;
        }
        error.clear();
        std::filesystem::remove(snapshots[index], error);
        if (error) {
            return false;
        }
    }
    return true;
}

bool PruneGeneratedRelationshipManifestSnapshots(
    const std::filesystem::path& folder) {
    std::error_code error;
    if (!std::filesystem::exists(folder, error)) {
        return !error;
    }
    std::vector<std::filesystem::path> snapshots;
    std::filesystem::directory_iterator iterator(folder, error);
    const std::filesystem::directory_iterator end;
    while (!error && iterator != end) {
        const std::filesystem::directory_entry& entry = *iterator;
        const std::filesystem::file_status status =
            entry.symlink_status(error);
        if (error) break;
        if (std::filesystem::is_regular_file(status) &&
            IsGeneratedRelationshipManifestSnapshotName(entry.path())) {
            snapshots.push_back(entry.path());
        }
        iterator.increment(error);
    }
    if (error) return false;
    std::sort(
        snapshots.begin(), snapshots.end(),
        [](const std::filesystem::path& first,
           const std::filesystem::path& second) {
            return first.filename().wstring() >
                   second.filename().wstring();
        });
    std::set<std::wstring> retainedDailyDates;
    constexpr std::size_t kPrefixLength = 14; // "relationships-"
    for (std::size_t index = kHistoryRecentSnapshotCount;
         index < snapshots.size(); ++index) {
        const std::wstring name = snapshots[index].filename().wstring();
        const std::wstring date = name.substr(kPrefixLength, 8);
        if (retainedDailyDates.size() < kHistoryDailySnapshotCount &&
            retainedDailyDates.insert(date).second) {
            continue;
        }
        error.clear();
        std::filesystem::remove(snapshots[index], error);
        if (error) return false;
    }
    return true;
}

