    static bool FilePathExists(const std::wstring& path) {
        return !path.empty() &&
               GetFileAttributesW(path.c_str()) !=
                   INVALID_FILE_ATTRIBUTES;
    }

    static std::filesystem::path AvailableDesktopRestoreDestination(
        const std::filesystem::path& desktop,
        const std::filesystem::path& requested,
        const std::set<std::wstring>& reservedDestinations) {
        const std::filesystem::path original = desktop / requested.filename();
        const auto available = [&reservedDestinations](
                                   const std::filesystem::path& candidate) {
            return !FilePathExists(candidate.wstring()) &&
                   !reservedDestinations.contains(
                       NormalizePath(candidate.wstring()));
        };
        if (available(original)) return original;

        const std::wstring stem = requested.stem().wstring();
        const std::wstring extension = requested.extension().wstring();
        for (int index = 2; index <= 9999; ++index) {
            const std::filesystem::path candidate = desktop /
                (stem + L"（引力桌面还原 " + std::to_wstring(index) +
                 L"）" + extension);
            if (available(candidate)) return candidate;
        }
        return {};
    }

    static void NotifyShellFileMove(
        const std::wstring& source,
        const std::wstring& destination) {
        const std::wstring sourceParent = NormalizePath(
            std::filesystem::path(source).parent_path().wstring());
        const std::wstring destinationParent = NormalizePath(
            std::filesystem::path(destination).parent_path().wstring());
        if (PathEquals(sourceParent, destinationParent)) {
            SHChangeNotify(
                SHCNE_RENAMEITEM, SHCNF_PATHW,
                source.c_str(), destination.c_str());
            return;
        }

        // A cross-directory move is a deletion in the source folder and a
        // creation in the destination folder. Reporting it as a rename alone
        // can leave Explorer's Desktop view stale, even though the file has
        // already been restored successfully.
        SHChangeNotify(SHCNE_DELETE, SHCNF_PATHW, source.c_str(), nullptr);
        SHChangeNotify(SHCNE_CREATE, SHCNF_PATHW,
                       destination.c_str(), nullptr);
        SHChangeNotify(SHCNE_UPDATEDIR, SHCNF_PATHW,
                       sourceParent.c_str(), nullptr);
        SHChangeNotify(SHCNE_UPDATEDIR, SHCNF_PATHW,
                       destinationParent.c_str(), nullptr);
    }

    bool MoveFileWithoutReplacement(
        const std::wstring& source,
        const std::wstring& destination,
        std::wstring* error = nullptr) const {
        if (source.empty() || destination.empty() ||
            !FilePathExists(source)) {
            if (error != nullptr) *error = L"源文件不存在";
            return false;
        }
        if (FilePathExists(destination)) {
            if (error != nullptr) *error = L"目标位置已存在同名文件";
            return false;
        }
        std::error_code filesystemError;
        std::filesystem::create_directories(
            std::filesystem::path(destination).parent_path(),
            filesystemError);
        if (filesystemError) {
            if (error != nullptr) *error = L"无法创建托管目录";
            return false;
        }
        if (MoveFileExW(
                source.c_str(), destination.c_str(),
                MOVEFILE_WRITE_THROUGH) == FALSE) {
            if (error != nullptr) {
                *error = L"移动真实文件失败（Windows 错误 " +
                    std::to_wstring(GetLastError()) + L"）";
            }
            return false;
        }
        NotifyShellFileMove(source, destination);
        return true;
    }

    static bool IsReservedWindowsFileStem(const std::wstring& stem) {
        std::wstring upper = stem;
        std::transform(
            upper.begin(), upper.end(), upper.begin(),
            [](wchar_t value) {
                return static_cast<wchar_t>(std::towupper(value));
            });
        if (upper == L"CON" || upper == L"PRN" || upper == L"AUX" ||
            upper == L"NUL") {
            return true;
        }
        if (upper.size() == 4 &&
            (upper.rfind(L"COM", 0) == 0 || upper.rfind(L"LPT", 0) == 0)) {
            return upper[3] >= L'1' && upper[3] <= L'9';
        }
        return false;
    }

    static bool ValidateFileRenameStem(
        const std::wstring& stem, std::wstring* reason = nullptr) {
        if (stem.empty() || stem == L"." || stem == L"..") {
            if (reason != nullptr) *reason = L"文件名不能为空";
            return false;
        }
        if (stem.back() == L'.' || stem.back() == L' ') {
            if (reason != nullptr) *reason = L"文件名不能以句点或空格结尾";
            return false;
        }
        if (stem.find_first_of(L"\\\\/:*?\"<>|") != std::wstring::npos) {
            if (reason != nullptr) *reason = L"文件名包含 Windows 不允许的字符";
            return false;
        }
        if (IsReservedWindowsFileStem(stem)) {
            if (reason != nullptr) *reason = L"该名称是 Windows 保留名称";
            return false;
        }
        return true;
    }

    bool CommitItemDisplayRename(
        std::uint64_t coreId, std::uint64_t itemId,
        const std::wstring& value) {
        FileItem* item = FindItem(coreId, itemId);
        if (item == nullptr) return false;
        if (value.empty()) {
            SetStatus(L"显示名称不能为空");
            return false;
        }
        const std::wstring displayName = Shorten(value, 80);
        if (item->displayName == displayName) return true;
        const WorkspaceState before = state_;
        item->displayName = displayName;
        dirty_ = true;
        if (!SaveState()) {
            state_ = before;
            dirty_ = false;
            SetStatus(L"保存失败：显示名称未修改");
            return false;
        }
        PushUndo(before);
        SetStatus(L"已更新显示名称");
        return true;
    }

    bool RenameItemRealFile(
        std::uint64_t coreId, std::uint64_t itemId,
        const std::wstring& stem) {
        Core* core = FindCore(coreId);
        FileItem* item = FindItem(coreId, itemId);
        if (core == nullptr || item == nullptr) return false;
        if (stateRecoveryBlocked_) {
            SetStatus(L"状态处于保护模式；未重命名真实文件");
            return false;
        }
        if (item->missing || item->path.empty() || !FilePathExists(item->path)) {
            SetStatus(L"重命名失败：真实文件不存在");
            return false;
        }
        if (item->isDirectory) {
            SetStatus(L"当前版本请在资源管理器中重命名文件夹");
            return false;
        }
        std::wstring validationError;
        if (!ValidateFileRenameStem(stem, &validationError)) {
            SetStatus(L"重命名失败：" + validationError);
            return false;
        }
        const std::filesystem::path source(item->path);
        const std::wstring extension = source.extension().wstring();
        const std::wstring fileName = stem + extension;
        if (fileName.size() > 255) {
            SetStatus(L"重命名失败：文件名过长");
            return false;
        }
        const std::filesystem::path destination = source.parent_path() / fileName;
        if (PathEquals(source.wstring(), destination.wstring())) {
            SetStatus(L"名称未改变");
            return true;
        }
        if (FilePathExists(destination.wstring())) {
            SetStatus(L"重命名失败：同目录已存在同名文件");
            return false;
        }
        if (item->storageMode == FileStorageMode::Reference) {
            const std::wstring warning =
                L"将重命名真实文件：\n" + FileDisplayName(item->path) +
                L"\n\n依赖原路径的程序可能受影响。是否继续？";
            if (MessageBoxW(
                    window_, warning.c_str(), L"重命名真实文件",
                    MB_YESNO | MB_ICONWARNING | MB_DEFBUTTON2) != IDYES) {
                return false;
            }
        }

        const WorkspaceState before = state_;
        ManagedFileTransaction transaction;
        transaction.id = itemId;
        transaction.coreId = coreId;
        transaction.itemId = itemId;
        transaction.operation = ManagedTransactionOperation::Rename;
        transaction.stage = ManagedTransactionStage::Prepared;
        transaction.sourcePath = source.wstring();
        transaction.destinationPath = destination.wstring();
        transaction.itemPresentAfter = true;
        transaction.createdAt = UnixTimeNow();
        if (!PersistManagedTransaction(transaction)) {
            SetStatus(L"重命名失败：无法写入文件事务日志");
            return false;
        }
        std::wstring moveError;
        if (!MoveFileWithoutReplacement(
                transaction.sourcePath, transaction.destinationPath,
                &moveError)) {
            ClearManagedTransaction();
            SetStatus(L"重命名失败：" + moveError);
            return false;
        }
        transaction.stage = ManagedTransactionStage::FileMoved;
        if (!PersistManagedTransaction(transaction)) {
            std::wstring rollbackError;
            const bool rolledBack = MoveFileWithoutReplacement(
                transaction.destinationPath, transaction.sourcePath,
                &rollbackError);
            if (rolledBack) {
                transaction.stage = ManagedTransactionStage::RolledBack;
                (void)PersistManagedTransaction(transaction);
                ClearManagedTransaction();
            }
            SetStatus(L"重命名失败：事务记录未完成，已尝试回滚真实文件");
            return false;
        }

        WorkspaceState candidate = state_;
        auto candidateCore = std::find_if(
            candidate.cores.begin(), candidate.cores.end(),
            [coreId](const Core& value) { return value.id == coreId; });
        FileItem* candidateItem = nullptr;
        if (candidateCore != candidate.cores.end()) {
            auto candidateFile = std::find_if(
                candidateCore->files.begin(), candidateCore->files.end(),
                [itemId](const FileItem& value) { return value.id == itemId; });
            if (candidateFile != candidateCore->files.end()) {
                candidateItem = &*candidateFile;
            }
        }
        if (candidateItem != nullptr) {
            candidateItem->path = transaction.destinationPath;
            candidateItem->originalName = fileName;
            candidateItem->displayName =
                MakeDisplayName(transaction.destinationPath, candidateItem->isDirectory);
            candidateItem->missing = false;
            if (candidateItem->storageMode == FileStorageMode::Managed) {
                candidateItem->managedPath = transaction.destinationPath;
                if (!candidateItem->originalPath.empty()) {
                    candidateItem->originalPath =
                        (std::filesystem::path(candidateItem->originalPath)
                             .parent_path() / fileName).wstring();
                }
            }
        }
        const RelationValidationResult validation = ValidateRelationState(candidate);
        if (candidateItem == nullptr || !validation.IsValid() ||
            !WriteStateWithRelationshipManifest(candidate)) {
            std::wstring rollbackError;
            const bool rolledBack = MoveFileWithoutReplacement(
                transaction.destinationPath, transaction.sourcePath,
                &rollbackError);
            if (rolledBack) {
                transaction.stage = ManagedTransactionStage::RolledBack;
                (void)PersistManagedTransaction(transaction);
                ClearManagedTransaction();
            }
            SetStatus(candidateItem == nullptr
                ? L"重命名失败：文件节点状态已变化，已回滚真实文件"
                : !validation.IsValid()
                    ? L"重命名失败：关系校验未通过，已回滚真实文件"
                    : L"重命名失败：状态未保存，已回滚真实文件");
            return false;
        }

        state_ = std::move(candidate);
        dirty_ = false;
        CreateHistoryBackup(false);
        transaction.stage = ManagedTransactionStage::StateSaved;
        (void)PersistManagedTransaction(transaction);
        transaction.stage = ManagedTransactionStage::Committed;
        (void)PersistManagedTransaction(transaction);
        ClearManagedTransaction();
        PushUndo(before);
        ManagedFileTransaction reverse;
        reverse.id = transaction.id;
        reverse.coreId = coreId;
        reverse.itemId = itemId;
        reverse.operation = ManagedTransactionOperation::Rename;
        reverse.sourcePath = transaction.destinationPath;
        reverse.destinationPath = transaction.sourcePath;
        reverse.itemPresentAfter = true;
        reverse.createdAt = UnixTimeNow();
        managedUndoAction_ = ManagedUndoAction{{std::move(reverse)}};
        iconCache_.clear();
        iconShadowCache_.clear();
        layoutCache_.clear();
        layoutDirty_ = true;
        SetStatus(L"已重命名真实文件");
        Invalidate();
        return true;
    }

    bool IsPublicDesktopManagedFile(const std::wstring& path) const {
        const std::optional<std::filesystem::path> publicDesktop =
            PublicDesktopPath();
        if (!publicDesktop.has_value()) {
            return false;
        }
        const std::wstring normalized = NormalizePath(path);
        const std::wstring parent = NormalizePath(
            std::filesystem::path(normalized).parent_path().wstring());
        return PathEquals(parent, NormalizePath(publicDesktop->wstring()));
    }

    bool IsEligibleDesktopManagedFile(
        const std::wstring& path,
        std::wstring* reason = nullptr) const {
        const std::optional<std::filesystem::path> desktop =
            CurrentUserDesktopPath();
        if (!desktop.has_value()) {
            if (reason != nullptr) *reason = L"无法读取当前用户桌面路径";
            return false;
        }
        const std::wstring normalized = NormalizePath(path);
        const bool isLegacyLibraryShortcut = [&]() {
            const auto shortcut = ManagedLibraryDesktopShortcutPath();
            return shortcut.has_value() &&
                PathEquals(normalized, NormalizePath(shortcut->wstring()));
        }();
        const bool isSafetyCenterShortcut = [&]() {
            const auto shortcut = ManagedLibrarySafetyCenterShortcutPath();
            return shortcut.has_value() &&
                PathEquals(normalized, NormalizePath(shortcut->wstring()));
        }();
        if (isLegacyLibraryShortcut || isSafetyCenterShortcut) {
            if (reason != nullptr) {
                *reason = L"“引力桌面安全中心”是受保护的恢复入口";
            }
            return false;
        }
        const std::wstring parent = NormalizePath(
            std::filesystem::path(normalized).parent_path().wstring());
        const bool onCurrentUserDesktop =
            PathEquals(parent, NormalizePath(desktop->wstring()));
        const bool onPublicDesktop = IsPublicDesktopManagedFile(normalized);
        if (!onCurrentUserDesktop && !onPublicDesktop) {
            if (reason != nullptr) {
                *reason = L"该文件不在当前用户桌面或公共桌面目录";
            }
            return false;
        }
        if (IsTransientDesktopArtifactName(normalized)) {
            if (reason != nullptr) {
                *reason = L"临时或系统桌面文件不能收纳";
            }
            return false;
        }
        const DWORD attributes = GetFileAttributesW(normalized.c_str());
        if (attributes == INVALID_FILE_ATTRIBUTES) {
            if (reason != nullptr) *reason = L"源文件不存在";
            return false;
        }
        if ((attributes & FILE_ATTRIBUTE_DIRECTORY) != 0 ||
            (attributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0 ||
            (attributes & FILE_ATTRIBUTE_OFFLINE) != 0) {
            if (reason != nullptr) {
                *reason = L"当前仅支持收纳本地普通文件和快捷方式";
            }
            return false;
        }
        return true;
    }

    bool StateMatchesManagedTransaction(
        const ManagedFileTransaction& transaction) {
        Core* owner = nullptr;
        FileItem* item = FindItemAnywhere(transaction.itemId, &owner);
        if (!transaction.itemPresentAfter) {
            return item == nullptr;
        }
        if (transaction.operation == ManagedTransactionOperation::Undo) {
            return item != nullptr && owner != nullptr &&
                   PathEquals(item->path, transaction.destinationPath);
        }
        if (transaction.operation == ManagedTransactionOperation::Rename ||
            transaction.operation ==
                ManagedTransactionOperation::ReorganizeLibrary) {
            return item != nullptr && owner != nullptr &&
                   PathEquals(item->path, transaction.destinationPath);
        }
        return item != nullptr && owner != nullptr &&
               item->storageMode == FileStorageMode::Managed &&
               PathEquals(item->path, transaction.destinationPath);
    }

    bool RollBackManagedBatchFiles(
        const ManagedBatchTransaction& transaction,
        std::wstring* errorMessage = nullptr) {
        for (auto iterator = transaction.moves.rbegin();
             iterator != transaction.moves.rend(); ++iterator) {
            const bool sourceExists = FilePathExists(iterator->sourcePath);
            const bool destinationExists =
                FilePathExists(iterator->destinationPath);
            if (sourceExists && !destinationExists) {
                continue;
            }
            if (!destinationExists || sourceExists) {
                if (errorMessage != nullptr) {
                    *errorMessage = L"源位置与目标位置状态不一致";
                }
                return false;
            }
            std::wstring moveError;
            if (!MoveFileWithoutReplacement(
                    iterator->destinationPath, iterator->sourcePath,
                    &moveError)) {
                if (errorMessage != nullptr) {
                    *errorMessage = moveError;
                }
                return false;
            }
        }
        return true;
    }

    void RecoverPendingManagedBatchTransaction() {
        const std::filesystem::path journalPath =
            ManagedBatchTransactionPath();
        if (journalPath.empty()) return;
        const std::optional<std::string> text = ReadUtf8File(journalPath);
        if (!text.has_value()) return;
        ManagedBatchTransaction transaction;
        if (!DeserializeManagedBatchTransaction(*text, transaction)) {
            SetStatus(
                L"检测到无效的批量托管事务日志；未移动任何真实文件");
            return;
        }
        if (stateRecoveryBlocked_) {
            SetStatus(
                L"状态处于保护模式；批量托管事务等待人工恢复");
            return;
        }
        const bool stateCommitted = std::all_of(
            transaction.moves.begin(), transaction.moves.end(),
            [this](const ManagedFileTransaction& move) {
                return StateMatchesManagedTransaction(move);
            });
        const bool allAtDestination = std::all_of(
            transaction.moves.begin(), transaction.moves.end(),
            [](const ManagedFileTransaction& move) {
                return FilePathExists(move.destinationPath) &&
                       !FilePathExists(move.sourcePath);
            });
        if (stateCommitted && allAtDestination) {
            ClearManagedBatchTransaction();
            SetStatus(L"已完成上次中断的批量文件事务");
            return;
        }
        if (!stateCommitted) {
            std::wstring rollbackError;
            if (RollBackManagedBatchFiles(transaction, &rollbackError)) {
                ClearManagedBatchTransaction();
                SetStatus(L"已完整回滚上次中断的批量文件事务");
            } else {
                SetStatus(
                    L"批量文件事务需要人工恢复；真实文件未被删除：" +
                    rollbackError);
            }
            return;
        }
        SetStatus(
            L"批量文件事务状态不一致；请通过文件库检查真实文件");
    }

    void RecoverPendingCoreDissolveTransaction() {
        const std::filesystem::path journalPath =
            CoreDissolveTransactionPath();
        if (journalPath.empty()) return;
        const std::optional<std::string> text = ReadUtf8File(journalPath);
        if (!text.has_value()) return;
        CoreDissolveTransaction transaction;
        if (!DeserializeCoreDissolveTransaction(*text, transaction)) {
            SetStatus(L"检测到无效的核心解散事务日志；未移动任何真实文件");
            return;
        }
        if (stateRecoveryBlocked_) {
            SetStatus(L"状态处于保护模式；核心解散事务等待人工恢复");
            return;
        }

        const bool coreStillPresent = FindCore(transaction.coreId) != nullptr;
        const bool allReferencesRemoved = std::all_of(
            transaction.moves.begin(), transaction.moves.end(),
            [this](const ManagedFileTransaction& move) {
                return FindItemAnywhere(move.itemId) == nullptr;
            });
        bool allAtSource = true;
        bool allAtDestination = true;
        for (const ManagedFileTransaction& move : transaction.moves) {
            const bool sourceExists = FilePathExists(move.sourcePath);
            const bool destinationExists = FilePathExists(move.destinationPath);
            allAtSource = allAtSource && sourceExists && !destinationExists;
            allAtDestination = allAtDestination &&
                destinationExists && !sourceExists;
        }

        const bool stateCommitted = transaction.retainSystemCore
            ? allReferencesRemoved
            : !coreStillPresent;
        if (stateCommitted && allAtDestination) {
            ClearCoreDissolveTransaction();
            SetStatus(L"已完成上次中断的核心解散");
            return;
        }

        if (!stateCommitted) {
            bool restored = true;
            for (auto iterator = transaction.moves.rbegin();
                 iterator != transaction.moves.rend(); ++iterator) {
                const bool sourceExists = FilePathExists(iterator->sourcePath);
                const bool destinationExists =
                    FilePathExists(iterator->destinationPath);
                if (sourceExists && !destinationExists) {
                    continue;
                }
                if (!destinationExists || sourceExists) {
                    restored = false;
                    break;
                }
                std::wstring error;
                if (!MoveFileWithoutReplacement(
                        iterator->destinationPath, iterator->sourcePath,
                        &error)) {
                    restored = false;
                    break;
                }
            }
            if (restored) {
                ClearCoreDissolveTransaction();
                SetStatus(L"已回滚未完成的核心解散；文件仍保留在原核心");
            } else {
                SetStatus(L"核心解散事务需要人工恢复；真实文件未被删除");
            }
            return;
        }

        (void)allAtSource;
        SetStatus(L"核心解散事务需要人工恢复；请通过文件库检查真实文件");
    }

    void RecoverPendingManagedTransaction() {
        const std::filesystem::path journalPath = ManagedTransactionPath();
        if (journalPath.empty()) return;
        const std::optional<std::string> text = ReadUtf8File(journalPath);
        if (!text.has_value()) return;
        ManagedFileTransaction transaction;
        if (!DeserializeManagedFileTransaction(*text, transaction)) {
            SetStatus(L"检测到无效的托管事务日志；未移动任何真实文件");
            return;
        }
        if (stateRecoveryBlocked_) {
            SetStatus(L"状态处于保护模式；托管事务等待人工恢复");
            return;
        }
        const bool sourceExists = FilePathExists(transaction.sourcePath);
        const bool destinationExists =
            FilePathExists(transaction.destinationPath);
        if (StateMatchesManagedTransaction(transaction) &&
            destinationExists) {
            transaction.stage = ManagedTransactionStage::Committed;
            (void)PersistManagedTransaction(transaction);
            ClearManagedTransaction();
            SetStatus(L"已完成上次中断的文件托管事务");
            return;
        }
        if (sourceExists && !destinationExists) {
            ClearManagedTransaction();
            SetStatus(L"已取消未完成的文件托管事务；源文件保持原位");
            return;
        }
        if (destinationExists && !sourceExists) {
            std::wstring rollbackError;
            if (MoveFileWithoutReplacement(
                    transaction.destinationPath, transaction.sourcePath,
                    &rollbackError)) {
                transaction.stage = ManagedTransactionStage::RolledBack;
                (void)PersistManagedTransaction(transaction);
                ClearManagedTransaction();
                SetStatus(L"已回滚未完成的文件托管事务");
            } else {
                SetStatus(L"托管事务需要修复：" + rollbackError);
            }
            return;
        }
        SetStatus(L"托管事务需要人工修复：源位置和目标位置状态不一致");
    }

    void NotifyPendingSessionEndRecovery() {
        const std::filesystem::path path =
            SessionEndRecoveryPath();
        if (!path.empty() &&
            GetFileAttributesW(path.c_str()) !=
                INVALID_FILE_ATTRIBUTES) {
            SetStatus(
                L"检测到上次关机保存失败的恢复副本：" +
                path.filename().wstring() +
                L"。可通过“导入布局”恢复。");
        }
    }

    std::filesystem::path CoreShortLabelOverridePath() const {
        if (stateFile_.empty()) {
            return {};
        }
        return std::filesystem::path(
            stateFile_.wstring() + L".core-short-labels.json");
    }

    std::string SerializeCoreShortLabelOverrides() const {
        std::ostringstream output;
        output.imbue(std::locale::classic());
        output << "{\"version\":1,\"labels\":[";
        bool first = true;
        for (const auto& [coreId, label] : protectedShortLabelOverrides_) {
            if (!first) output << ',';
            first = false;
            output << "{\"core_id\":" << coreId
                   << ",\"short_label\":" << EscapeJson(label) << '}';
        }
        output << "]}";
        return output.str();
    }

    void LoadCoreShortLabelOverrides() {
        protectedShortLabelOverrides_.clear();
        const std::filesystem::path path = CoreShortLabelOverridePath();
        if (path.empty()) {
            return;
        }
        const std::optional<std::string> text = ReadUtf8File(path);
        if (!text.has_value()) {
            return;
        }
        JsonValue rootValue;
        JsonParser parser(*text);
        if (!parser.Parse(rootValue)) {
            return;
        }
        const JsonValue::Object* root = rootValue.AsObject();
        const JsonValue* labelsValue =
            root == nullptr ? nullptr : FindMember(*root, "labels");
        const JsonValue::Array* labels =
            labelsValue == nullptr ? nullptr : labelsValue->AsArray();
        if (labels == nullptr) {
            return;
        }
        for (const JsonValue& entry : *labels) {
            const JsonValue::Object* object = entry.AsObject();
            if (object == nullptr) continue;
            const std::uint64_t coreId = static_cast<std::uint64_t>(
                NumberMember(*object, "core_id", 0.0));
            const std::wstring label =
                StringMember(*object, "short_label", L"");
            if (coreId == 0 ||
                ValidateCoreShortLabel(label) !=
                    CoreShortLabelValidation::Valid) {
                continue;
            }
            if (Core* core = FindCore(coreId); core != nullptr) {
                core->shortLabel = label;
                protectedShortLabelOverrides_[coreId] = label;
            }
        }
    }

    bool PersistCoreShortLabelOverrides() {
        const std::filesystem::path path = CoreShortLabelOverridePath();
        return !path.empty() &&
               WriteUtf8Atomic(
                   path, SerializeCoreShortLabelOverrides());
    }

    void SynchronizeProtectedShortLabelOverridesFromState() {
        protectedShortLabelOverrides_.clear();
        for (const Core& core : state_.cores) {
            protectedShortLabelOverrides_[core.id] = core.shortLabel;
        }
    }

    bool TryRepairLoadedRelationState(
        const std::filesystem::path& sourcePath,
        const std::string& originalText,
        const WorkspaceState& loaded,
        const RelationValidationResult& validation,
        std::filesystem::path* preservedPath) {
        (void)PreserveInvalidRelationStateCopy(
            sourcePath, originalText, validation,
            preservedPath);
        WorkspaceState repaired;
        RelationRepairSummary summary;
        if (!RepairRecoverableRelationState(
                loaded, repaired, summary) ||
            !ValidateRelationState(repaired).IsValid() ||
            stateFile_.empty() ||
            !WriteUtf8Atomic(
                stateFile_, SerializeState(repaired))) {
            return false;
        }
        state_ = std::move(repaired);
        stateRecoveryBlocked_ = false;
        dirty_ = false;
        SetStatus(
            L"已安全修复异常文件关系：断开 " +
            std::to_wstring(summary.clearedParents) +
            L" 条失效上层连接，清理 " +
            std::to_wstring(summary.removedFamilies) +
            L" 个失效文件族；文件引用和真实文件均已保留");
        NotifyPendingSessionEndRecovery();
        return true;
    }

    int DividerHandleWidthPixels() const {
        return std::max(1, DipToPixels(100.0f));
    }

    int DividerHandleHeightPixels() const {
        return std::max(1, DipToPixels(60.0f));
    }

    std::array<POINT, 3> DividerInteractionTrianglePoints(
        int centerX) const {
        const int halfWidth = DividerHandleWidthPixels() / 2;
        const int tipY = std::min(
            DividerHandleHeightPixels() - 1,
            std::max(1, DipToPixels(46.0f)));
        return {
            POINT{centerX - halfWidth, 0},
            POINT{centerX + halfWidth, 0},
            POINT{centerX, tipY},
        };
    }

    void UpdateDividerHandleHitRegion() {
        if (dividerHandleWindow_ == nullptr ||
            IsWindow(dividerHandleWindow_) == FALSE) {
            return;
        }
        const int width = DividerHandleWidthPixels();
        const int centerX = width / 2;
        const auto points = DividerInteractionTrianglePoints(centerX);
        if (HRGN region = CreatePolygonRgn(
                points.data(), static_cast<int>(points.size()), WINDING);
            region != nullptr) {
            // SetWindowRgn takes ownership on success. The region makes the
            // entire inverted-triangle surface draggable while allowing the
            // rest of the tiny island to remain mouse-through.
            if (SetWindowRgn(dividerHandleWindow_, region, FALSE) == 0) {
                DeleteObject(region);
            }
        }
    }

    void UpdateDividerHandleVisual() {
        if (dividerHandleWindow_ == nullptr ||
            IsWindow(dividerHandleWindow_) == FALSE) {
            return;
        }
        const BYTE alpha = (dividerHovered_ || draggingDivider_)
            ? 255 : 92;
        SetLayeredWindowAttributes(
            dividerHandleWindow_, RGB(255, 0, 255), alpha,
            LWA_COLORKEY | LWA_ALPHA);
        InvalidateRect(dividerHandleWindow_, nullptr, FALSE);
    }

    void PresentDividerHandleImmediately() {
        if (!DividerEnabled() || state_.workspacePaused ||
            !workspaceVisible_ || window_ == nullptr ||
            IsWindow(window_) == FALSE) {
            return;
        }
        if (dividerHandleWindow_ == nullptr ||
            IsWindow(dividerHandleWindow_) == FALSE) {
            dividerHandleWindow_ = nullptr;
            if (!CreateDividerHandleWindow()) {
                AppendRuntimeDiagnostic(
                    "divider_handle_pointer_recreate_failed",
                    HRESULT_FROM_WIN32(GetLastError()), GetLastError());
                return;
            }
        } else {
            SyncDividerHandleWindowFrame();
        }
        if (dividerHandleWindow_ != nullptr &&
            IsWindow(dividerHandleWindow_) != FALSE) {
            ShowWindow(dividerHandleWindow_, SW_SHOWNOACTIVATE);
            RedrawWindow(
                dividerHandleWindow_, nullptr, nullptr,
                RDW_INVALIDATE | RDW_UPDATENOW | RDW_NOERASE);
        }
    }

    void SyncDividerHandleWindowFrame() {
        if (dividerHandleWindow_ == nullptr ||
            IsWindow(dividerHandleWindow_) == FALSE) {
            return;
        }
        AttachDividerHandleWindowToCompanionLayer();
        if (!DividerEnabled() || state_.workspacePaused ||
            !workspaceVisible_ || window_ == nullptr ||
            IsWindow(window_) == FALSE) {
            dividerHandleMouseTracking_ = false;
            dividerHovered_ = false;
            HideDividerTooltip();
            ShowWindow(dividerHandleWindow_, SW_HIDE);
            return;
        }
        const int width = DividerHandleWidthPixels();
        const int height = DividerHandleHeightPixels();
        RECT visualBounds{};
        HWND host = GetParent(dividerHandleWindow_);
        if (GetWindowRect(window_, &visualBounds) == FALSE ||
            host == nullptr || IsWindow(host) == FALSE) {
            return;
        }
        // Place this desktop-host child one half-width to the left of the
        // visual workspace. Its centre is therefore exactly on the divider,
        // while its lifecycle remains independent of interaction-window
        // recreation.
        POINT origin{
            visualBounds.left - width / 2,
            visualBounds.top};
        ScreenToClient(host, &origin);
        SetWindowPos(
            dividerHandleWindow_,
            HWND_TOP,
            origin.x, origin.y,
            width, height,
            SWP_NOACTIVATE |
            SWP_SHOWWINDOW);
        UpdateDividerHandleHitRegion();
        UpdateDividerHandleVisual();
        UpdateDividerTooltipRectangle();
    }

    bool CreateDividerHandleWindow() {
        if (dividerHandleWindow_ != nullptr &&
            IsWindow(dividerHandleWindow_) != FALSE) {
            SyncDividerHandleWindowFrame();
            return true;
        }
        constexpr DWORD handleStyle = WS_POPUP;
        constexpr DWORD handleExStyle =
            WS_EX_TOOLWINDOW | WS_EX_LAYERED |
            WS_EX_NOACTIVATE;
        HWND handle = CreateWindowExW(
            handleExStyle, kDividerHandleWindowClass, L"",
            handleStyle, 0, 0, 1, 1,
            nullptr, nullptr, GetModuleHandleW(nullptr), this);
        if (handle == nullptr) {
            return false;
        }
        dividerHandleWindow_ = handle;
        SetLayeredWindowAttributes(
            dividerHandleWindow_, RGB(255, 0, 255), 92,
            LWA_COLORKEY | LWA_ALPHA);
        CreateDividerTooltip();
        SyncDividerHandleWindowFrame();
        return true;
    }

    void DestroyDividerHandleWindow() {
        DestroyDividerTooltip();
        if (dividerHandleWindow_ == nullptr) {
            return;
        }
        dividerHandleMouseTracking_ = false;
        if (draggingDivider_) {
            CancelDividerDrag();
        } else {
            dividerHovered_ = false;
        }
        HWND handle = dividerHandleWindow_;
        dividerHandleWindow_ = nullptr;
        DestroyWindow(handle);
    }

    void PaintDividerHandleWindow(HWND source) {
        PAINTSTRUCT paint{};
        HDC dc = BeginPaint(source, &paint);
        RECT client{};
        GetClientRect(source, &client);
        constexpr COLORREF transparentKey = RGB(255, 0, 255);
        HBRUSH background = CreateSolidBrush(transparentKey);
        FillRect(dc, &client, background);
        DeleteObject(background);

        const int centerX = (client.left + client.right) / 2;
        const int top = std::max(1, DipToPixels(5.0f));
        const int lineHeight = std::max(2, DipToPixels(3.0f));
        const int gap = std::max(2, DipToPixels(3.0f));
        // Keep only the upper guide strokes separate.  The endpoint itself is
        // one filled triangle, with its straight top edge serving as the final
        // horizontal stroke.  No rounded bar is overlaid on that triangle.
        const std::array<float, 5> widths{
            98.0f, 82.0f, 66.0f, 50.0f, 34.0f};
        const bool active = dividerHovered_ || draggingDivider_;
        const COLORREF lineColor = active
            ? RGB(0, 0, 0)
            : RGB(73, 82, 88);
        HBRUSH lineBrush = CreateSolidBrush(lineColor);
        HPEN noOutline = CreatePen(PS_NULL, 1, lineColor);
        HGDIOBJ oldBrush = SelectObject(dc, lineBrush);
        HGDIOBJ oldPen = SelectObject(dc, noOutline);
        for (std::size_t index = 0; index < widths.size(); ++index) {
            const int width = std::max(2, DipToPixels(widths[index]));
            const int y = top + static_cast<int>(index) *
                (lineHeight + gap);
            const int left = centerX - width / 2;
            // A small beveled polygon keeps the guide strokes soft without
            // importing GDI32!RoundRect, which caused a loader-compatibility
            // failure on this desktop.
            const int bevel = std::max(
                1, std::min(lineHeight / 2, width / 4));
            const POINT stroke[] = {
                {left + bevel, y},
                {left + width - bevel, y},
                {left + width, y + lineHeight / 2},
                {left + width - bevel, y + lineHeight},
                {left + bevel, y + lineHeight},
                {left, y + lineHeight / 2},
            };
            Polygon(dc, stroke, static_cast<int>(std::size(stroke)));
        }
        const int tipBaseY = top + static_cast<int>(widths.size()) *
            (lineHeight + gap);
        const int tipHalfWidth = std::max(2, DipToPixels(12.0f));
        const int tipY = std::min(
            static_cast<int>(client.bottom) - 1,
            tipBaseY + std::max(1, DipToPixels(8.0f)));
        const POINT tip[] = {
            {centerX - tipHalfWidth, tipBaseY},
            {centerX + tipHalfWidth, tipBaseY},
            {centerX, tipY},
        };
        HBRUSH tipBrush = CreateSolidBrush(RGB(0, 0, 0));
        HGDIOBJ oldTipBrush = SelectObject(dc, tipBrush);
        Polygon(dc, tip, static_cast<int>(std::size(tip)));
        SelectObject(dc, oldTipBrush);
        DeleteObject(tipBrush);
        SelectObject(dc, oldPen);
        SelectObject(dc, oldBrush);
        DeleteObject(noOutline);
        DeleteObject(lineBrush);
        EndPaint(source, &paint);
    }

    void UpdateDividerTooltipRectangle() {
        if (dividerTooltipWindow_ == nullptr ||
            interactionWindow_ == nullptr) {
            return;
        }
        TOOLINFOW tool{};
        tool.cbSize = TTTOOLINFOW_V1_SIZE;
        tool.hwnd = interactionWindow_;
        tool.uId = 1;
        tool.rect = RECT{
            0, 0,
            DividerHandleWidthPixels(),
            std::min(DividerHandleHeightPixels(),
                     std::max(1, DipToPixels(46.0f)))};
        SendMessageW(
            dividerTooltipWindow_, TTM_NEWTOOLRECTW,
            0, reinterpret_cast<LPARAM>(&tool));
    }

    void CreateDividerTooltip() {
        if (dividerTooltipWindow_ != nullptr ||
            interactionWindow_ == nullptr) {
            return;
        }
        INITCOMMONCONTROLSEX controls{
            sizeof(controls), ICC_WIN95_CLASSES};
        InitCommonControlsEx(&controls);
        dividerTooltipWindow_ = CreateWindowExW(
            WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE,
            TOOLTIPS_CLASSW, nullptr,
            WS_POPUP | TTS_NOPREFIX | TTS_ALWAYSTIP,
            CW_USEDEFAULT, CW_USEDEFAULT,
            CW_USEDEFAULT, CW_USEDEFAULT,
            interactionWindow_, nullptr,
            GetModuleHandleW(nullptr), nullptr);
        if (dividerTooltipWindow_ == nullptr) {
            return;
        }
        TOOLINFOW tool{};
        tool.cbSize = TTTOOLINFOW_V1_SIZE;
        tool.uFlags = TTF_SUBCLASS;
        tool.hwnd = interactionWindow_;
        tool.uId = 1;
        tool.lpszText = const_cast<LPWSTR>(
            L"拖动调整核心桌面范围");
        tool.rect = RECT{
            0, 0,
            DividerHandleWidthPixels(),
            std::min(DividerHandleHeightPixels(),
                     std::max(1, DipToPixels(46.0f)))};
        SendMessageW(
            dividerTooltipWindow_, TTM_ADDTOOLW,
            0, reinterpret_cast<LPARAM>(&tool));
        SendMessageW(
            dividerTooltipWindow_, TTM_UPDATETIPTEXTW,
            0, reinterpret_cast<LPARAM>(&tool));
        SendMessageW(
            dividerTooltipWindow_, TTM_SETDELAYTIME,
            TTDT_INITIAL, MAKELPARAM(420, 0));
        SendMessageW(
            dividerTooltipWindow_, TTM_SETDELAYTIME,
            TTDT_RESHOW, MAKELPARAM(80, 0));
        SetWindowPos(
            dividerTooltipWindow_, HWND_TOPMOST,
            0, 0, 0, 0,
            SWP_NOMOVE | SWP_NOSIZE |
                SWP_NOACTIVATE | SWP_NOOWNERZORDER);
    }

    void HideDividerTooltip() {
        if (dividerTooltipWindow_ != nullptr) {
            SendMessageW(dividerTooltipWindow_, TTM_POP, 0, 0);
        }
    }

    void DestroyDividerTooltip() {
        if (dividerTooltipWindow_ == nullptr) {
            return;
        }
        HWND tooltip = dividerTooltipWindow_;
        dividerTooltipWindow_ = nullptr;
        DestroyWindow(tooltip);
    }

    void LoadState() {
        stateFile_ = StateFilePath();
        const std::optional<std::string> stateText = ReadUtf8File(stateFile_);
        if (stateText) {
            WorkspaceState loaded;
            bool automaticCoreNameMigrated = false;
            if (DeserializeState(*stateText, loaded,
                                 &automaticCoreNameMigrated)) {
                const RelationValidationResult validation =
                    ValidateRelationState(loaded);
                state_ = std::move(loaded);
                if (validation.IsValid()) {
                    dirty_ = automaticCoreNameMigrated;
                    NotifyPendingSessionEndRecovery();
                    return;
                }
                std::filesystem::path preserved;
                if (TryRepairLoadedRelationState(
                        stateFile_, *stateText, state_,
                        validation, &preserved)) {
                    return;
                }
                stateRecoveryBlocked_ = true;
                dirty_ = false;
                std::wstring message =
                    L"检测到非法文件关系，已原样载入只读保护模式；"
                    L"不会覆盖原状态。";
                if (!validation.issues.empty()) {
                    message += L" " +
                        validation.issues.front().subject +
                        L"：" +
                        validation.issues.front().reason;
                }
                if (!preserved.empty()) {
                    message += L" 异常副本：" +
                               preserved.filename().wstring();
                }
                SetStatus(std::move(message));
                return;
            }
        }
        const std::optional<std::string> backup =
            ReadUtf8File(stateFile_.wstring() + L".bak");
        if (backup) {
            WorkspaceState loaded;
            bool automaticCoreNameMigrated = false;
            if (DeserializeState(*backup, loaded,
                                 &automaticCoreNameMigrated)) {
                const RelationValidationResult validation =
                    ValidateRelationState(loaded);
                state_ = std::move(loaded);
                if (validation.IsValid()) {
                    SetStatus(L"主状态文件无效，已从备份恢复");
                    dirty_ = true;
                    NotifyPendingSessionEndRecovery();
                    return;
                }
                std::filesystem::path preserved;
                if (TryRepairLoadedRelationState(
                        stateFile_.wstring() + L".bak",
                        *backup, state_, validation,
                        &preserved)) {
                    return;
                }
                stateRecoveryBlocked_ = true;
                dirty_ = false;
                std::wstring message =
                    L"主状态无效，备份也含非法文件关系；"
                    L"已原样载入备份的只读保护模式。";
                if (!validation.issues.empty()) {
                    message += L" " +
                        validation.issues.front().subject +
                        L"：" +
                        validation.issues.front().reason;
                }
                SetStatus(std::move(message));
                return;
            }
        }
        const bool existingStateWasUnreadable = stateText.has_value() || backup.has_value();
        freshWorkspaceWithoutState_ = !existingStateWasUnreadable;
        Core unclassified;
        unclassified.id = kUnclassifiedCoreId;
        unclassified.name = L"未分类";
        unclassified.position = D2D1::Point2F(360.0f, 300.0f);
        unclassified.expanded = true;
        state_.cores.push_back(std::move(unclassified));
        state_.nextId = 2;
        state_.viewOffset = D2D1::Point2F(70.0f, 65.0f);
        state_.zoom = 1.0f;
        stateRecoveryBlocked_ = existingStateWasUnreadable;
        dirty_ = !existingStateWasUnreadable;
        if (existingStateWasUnreadable) {
            SetStatus(L"状态文件和备份均无法读取；原文件已保留，未覆盖。请导入备份或导出当前恢复副本。");
        }
    }

    void CreateBenchmarkWorkspace() {
        state_ = {};
        state_.nextId = 2;
        state_.viewOffset = D2D1::Point2F(40.0f, 60.0f);
        state_.zoom = 0.75f;
        for (int coreIndex = 0; coreIndex < 4; ++coreIndex) {
            Core core;
            core.id = coreIndex == 0 ? kUnclassifiedCoreId : state_.nextId++;
            core.name = coreIndex == 0 ? L"未分类"
                                       : L"性能核心 " + std::to_wstring(coreIndex);
            core.position = D2D1::Point2F(
                340.0f + static_cast<float>(coreIndex % 2) * 760.0f,
                300.0f + static_cast<float>(coreIndex / 2) * 600.0f);
            core.expanded = true;
            core.displayLimit = kNormalVisibleLimit;
            core.layoutVersion = kLayoutVersion;
            for (int itemIndex = 0;
                 itemIndex < kCoreFileCapacity; ++itemIndex) {
                FileItem item;
                item.id = state_.nextId++;
                item.path = L"C:\\GravityBenchmark\\core_" + std::to_wstring(coreIndex) +
                            L"_file_" + std::to_wstring(itemIndex) +
                            (itemIndex % 3 == 0 ? L".pdf"
                                               : (itemIndex % 3 == 1 ? L".png" : L".txt"));
                item.favorite = itemIndex == 0;
                item.missing = true;
                AssignNewItemLayout(core, item);
                core.files.push_back(std::move(item));
            }
            state_.cores.push_back(std::move(core));
        }
        dirty_ = false;
        undoStack_.clear();
    }

    bool SaveState() {
        if (benchmarkMode_ || !dirty_ || stateFile_.empty()) {
            return !stateRecoveryBlocked_;
        }
        if (stateRecoveryBlocked_) {
            SetStatus(L"状态恢复待处理：不会覆盖原始损坏文件");
            return false;
        }
        UpdateCoreRatios();
        if (WriteStateWithRelationshipManifest(state_)) {
            dirty_ = false;
            saveRetryAttempt_ = 0;
            CreateHistoryBackup(false);
            return true;
        } else {
            SetStatus(L"状态保存失败；当前内存中的布局仍然有效");
            return false;
        }
    }

    void Resize() {
        if (window_ == nullptr || IsIconic(window_)) {
            return;
        }
        RECT client{};
        GetClientRect(window_, &client);
        if (client.right <= 1 || client.bottom <= 1) {
            return;
        }
        if (renderTarget_ != nullptr) DiscardDeviceResources();
        if (draggingDivider_) {
            // During a divider drag redraw only the changed desktop boundary.
            // Core ratios, collision recovery and text resources are deferred
            // until mouse release so saved layouts are not continuously rebuilt.
            Invalidate();
            return;
        }
        ApplyCoreRatiosToWorkspace();
        RefreshResponsiveMetrics(true);
        PositionEditWindow();
        PositionCoreShortLabelEditWindow();
        Invalidate();
    }

    void OnDpiChanged(WPARAM wParam, LPARAM lParam) {
        dpi_ = static_cast<float>(HIWORD(wParam));
        RefreshWindowsVisualProfile();
        (void)lParam;
        // The suggested rectangle belongs to a movable normal window.  This
        // desktop companion must instead reacquire the current monitor work
        // area and remain attached to its right half/full-workspace mode.
        ApplyCompanionWorkspaceFrame();
        if (renderTarget_ != nullptr) DiscardDeviceResources();
        ApplyCoreRatiosToWorkspace();
        RefreshResponsiveMetrics(true);
        PositionEditWindow();
        PositionCoreShortLabelEditWindow();
        Invalidate();
    }

    void Invalidate() const {
        if (window_ != nullptr) {
            InvalidateRect(window_, nullptr, FALSE);
        }
    }

